import{bQ as e,aL as t,u as l,G as i}from"./chunks/framework.DaEK0KQB.js";const d=JSON.parse('{"title":"2分钟规则","description":"","frontmatter":{"title":"2分钟规则","date":"2020-11-09T11:05:29.000Z","permalink":"/pages/baaa02/","categories":["更多","实用技巧"],"tags":["实用技巧","文摘"],"author":{"name":"xugaoyi","link":"https://github.com/xugaoyi"}},"headers":[],"relativePath":"更多/实用技巧/01.2分钟规则.md","filePath":"更多/实用技巧/01.2分钟规则.md","lastUpdated":1785225860000}'),r={name:"更多/实用技巧/01.2分钟规则.md"};function o(n,a,_,s,p,u){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_2分钟规则" tabindex="-1">2分钟规则 <a class="header-anchor" href="#_2分钟规则" aria-label="Permalink to &quot;2分钟规则&quot;">​</a></h1><p>每当你发现很难开始执行某项任务时，可以试试将其缩减成2分钟的版本。</p><ul><li>看一本书 → 看一页书</li><li>写一篇文章 → 写一句话</li><li>跑10公里 → 穿上跑鞋</li><li>做100次俯卧撑 → 做1次俯卧撑</li><li>多吃蔬菜水果 → 吃一个水果</li><li>编写一个程序 → 编写一个函数 → 编写一行代码</li></ul><p>这样做的目的是使上手变得超级容易，让你先上手再说。一旦开始做了（这可能是最艰难的一步），你就会开始有动力，可能会继续做下去。</p><ul><li>阅读一页 → 阅读10页 → 读完第一章</li><li>写一个句子 → 写文章的开头 → 写出正文</li><li>穿上跑鞋 → 步行5分钟 → 跑步5分钟</li></ul><p>一旦开始，继续做下去就会容易得多。有时，你甚至会发现，自己在不知不觉间已经完成了任务。</p><blockquote><p>本文摘录自 <a href="https://hoanhan.co/2-minute-rule" target="_blank" rel="noreferrer">https://hoanhan.co/2-minute-rule</a></p></blockquote>',7)])])}const h=e(r,[["render",o]]);export{d as __pageData,h as default};
